/**
 * RealWorld reports failures as `{ "errors": { "<field>": ["<message>", ...] } }`.
 * `ApiError` carries that payload together with the HTTP status to answer with.
 */
export type ErrorBody = Record<string, string[]>;

export class ApiError extends Error {
  readonly statusCode: number;
  readonly errors: ErrorBody;

  constructor(statusCode: number, errors: ErrorBody) {
    super(`HTTP ${statusCode}: ${JSON.stringify(errors)}`);
    this.name = 'ApiError';
    this.statusCode = statusCode;
    this.errors = errors;
  }
}

const single = (field: string, message: string): ErrorBody => ({ [field]: [message] });

export const unprocessable = (errors: ErrorBody) => new ApiError(422, errors);
export const blank = (field: string) => new ApiError(422, single(field, "can't be blank"));
export const alreadyTaken = (field: string) => new ApiError(409, single(field, 'has already been taken'));
export const notFound = (resource: string) => new ApiError(404, single(resource, 'not found'));
export const forbidden = (resource: string) => new ApiError(403, single(resource, 'forbidden'));
export const missingToken = () => new ApiError(401, single('token', 'is missing'));
export const invalidToken = () => new ApiError(401, single('token', 'is invalid'));
export const invalidCredentials = () => new ApiError(401, single('credentials', 'invalid'));

