import { ApiError, blank, unprocessable } from './errors.js';

/** NIST SP 800-63B 5.1.1.2: at least 8 characters, and at least 64 must be accepted. */
export const PASSWORD_MIN_LENGTH = 8;
export const PASSWORD_MAX_LENGTH = 72;

export function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Unwraps the single top-level envelope key RealWorld wraps every payload in. */
export function envelope(body: unknown, key: string): Record<string, unknown> {
  if (!isPlainObject(body) || !isPlainObject(body[key])) {
    throw blank(key);
  }
  return body[key] as Record<string, unknown>;
}

/** A field is "present" when the client sent the key at all, even with a null value. */
export function present(payload: Record<string, unknown>, field: string): boolean {
  return Object.prototype.hasOwnProperty.call(payload, field);
}

/**
 * Reads a mandatory, non-blank string. Missing, null, non-string and
 * whitespace-only values all count as blank.
 */
export function requiredString(payload: Record<string, unknown>, field: string): string {
  const value = payload[field];
  if (typeof value !== 'string' || value.trim() === '') {
    throw blank(field);
  }
  return value;
}

/**
 * Reads a non-blank string that may be omitted entirely. Sending the key with a
 * null or blank value is an error — only leaving it out keeps the current value.
 */
export function optionalRequiredString(
  payload: Record<string, unknown>,
  field: string,
): string | undefined {
  if (!present(payload, field)) return undefined;
  return requiredString(payload, field);
}

/**
 * Reads a nullable string field (`bio`, `image`). Absent leaves the value
 * untouched; null and the empty string both normalize to null.
 */
export function nullableString(
  payload: Record<string, unknown>,
  field: string,
): string | null | undefined {
  if (!present(payload, field)) return undefined;
  const value = payload[field];
  if (value === null) return null;
  if (typeof value !== 'string') {
    throw unprocessable({ [field]: ['is invalid'] });
  }
  return value.trim() === '' ? null : value;
}

export function validatePassword(value: unknown): string {
  if (typeof value !== 'string' || value === '') {
    throw blank('password');
  }
  if (value.length < PASSWORD_MIN_LENGTH) {
    throw unprocessable({
      password: [`is too short (minimum is ${PASSWORD_MIN_LENGTH} characters)`],
    });
  }
  if (value.length > PASSWORD_MAX_LENGTH) {
    throw unprocessable({
      password: [`is too long (maximum is ${PASSWORD_MAX_LENGTH} characters)`],
    });
  }
  return value;
}

/**
 * Reads `tagList`. Omitting it leaves existing tags alone; an empty array clears
 * them. Anything that is not an array of strings — including null — is rejected.
 */
export function tagList(payload: Record<string, unknown>): string[] | undefined {
  if (!present(payload, 'tagList')) return undefined;
  const value = payload['tagList'];
  if (!Array.isArray(value) || value.some((tag) => typeof tag !== 'string')) {
    throw unprocessable({ tagList: ['is invalid'] });
  }
  const cleaned = (value as string[]).map((tag) => tag.trim()).filter((tag) => tag !== '');
  return [...new Set(cleaned)];
}

/** Parses a non-negative integer query parameter, falling back when unusable. */
export function intParam(raw: unknown, fallback: number, max?: number): number {
  if (typeof raw !== 'string' || raw.trim() === '') return fallback;
  const parsed = Number(raw);
  if (!Number.isInteger(parsed) || parsed < 0) return fallback;
  return max !== undefined ? Math.min(parsed, max) : parsed;
}

export { ApiError };

