import type { FastifyReply, FastifyRequest } from 'fastify';
import jwt from 'jsonwebtoken';
import bcrypt from 'bcryptjs';
import { invalidToken, missingToken } from './errors.js';
import { prisma } from './prisma.js';

const JWT_SECRET = process.env['JWT_SECRET'] ?? 'realworld-dev-secret-change-me';
const JWT_EXPIRES_IN = '30d';
const BCRYPT_ROUNDS = 10;

export type AuthenticatedUser = {
  id: number;
  username: string;
  email: string;
  bio: string | null;
  image: string | null;
};

declare module 'fastify' {
  interface FastifyRequest {
    currentUser: AuthenticatedUser | null;
  }
}

export const hashPassword = (plain: string) => bcrypt.hash(plain, BCRYPT_ROUNDS);
export const verifyPassword = (plain: string, hash: string) => bcrypt.compare(plain, hash);

export function signToken(userId: number): string {
  return jwt.sign({ sub: String(userId) }, JWT_SECRET, { expiresIn: JWT_EXPIRES_IN });
}

/**
 * RealWorld's scheme is `Authorization: Token <jwt>`; `Bearer` is accepted too
 * since several official front-ends send it.
 */
function extractToken(header: string | undefined): string | null {
  if (!header) return null;
  const match = /^(?:Token|Bearer)\s+(.+)$/i.exec(header.trim());
  return match?.[1]?.trim() || null;
}

async function resolveUser(request: FastifyRequest): Promise<AuthenticatedUser | null> {
  const raw = extractToken(request.headers.authorization);
  if (!raw) return null;

  let payload: jwt.JwtPayload;
  try {
    payload = jwt.verify(raw, JWT_SECRET) as jwt.JwtPayload;
  } catch {
    throw invalidToken();
  }

  const userId = Number(payload.sub);
  if (!Number.isInteger(userId)) throw invalidToken();

  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: { id: true, username: true, email: true, bio: true, image: true },
  });
  if (!user) throw invalidToken();
  return user;
}

/** Rejects the request unless a valid token is present. */
export async function requireAuth(request: FastifyRequest, _reply: FastifyReply): Promise<void> {
  if (!extractToken(request.headers.authorization)) {
    throw missingToken();
  }
  request.currentUser = await resolveUser(request);
}

/** Populates `currentUser` when a token is supplied, but allows anonymous access. */
export async function optionalAuth(request: FastifyRequest, _reply: FastifyReply): Promise<void> {
  request.currentUser = await resolveUser(request);
}

/** Narrowing helper for handlers guarded by `requireAuth`. */
export function currentUser(request: FastifyRequest): AuthenticatedUser {
  if (!request.currentUser) throw missingToken();
  return request.currentUser;
}

