input.content:
import { Prisma } from '@prisma/client';
import type { AuthenticatedUser } from './auth.js';
import { signToken } from './auth.js';
import { prisma } from './prisma.js';

/** Everything the article/comment serializers need loaded in one round trip. */
export const articleInclude = {
  author: true,
  tags: { include: { tag: true } },
  _count: { select: { favorites: true } },
} satisfies Prisma.ArticleInclude;

export const commentInclude = { author: true } satisfies Prisma.CommentInclude;

export type ArticleWithRelations = Prisma.ArticleGetPayload<{ include: typeof articleInclude }>;
export type CommentWithRelations = Prisma.CommentGetPayload<{ include: typeof commentInclude }>;

type ProfileSource = {
  username: string;
  bio: string | null;
  image: string | null;
};

/**
 * Per-request memo of "which of these authors do I follow" and "which of these
 * articles have I favorited", so serializing a list stays at two extra queries.
 */
export type Viewer = {
  id: number | null;
  followedUserIds: Set<number>;
  favoritedArticleIds: Set<number>;
};

export const anonymousViewer = (): Viewer => ({
  id: null,
  followedUserIds: new Set(),
  favoritedArticleIds: new Set(),
});

export async function buildViewer(
  userId: number | null,
  articles: ArticleWithRelations[] = [],
  extraUserIds: number[] = [],
): Promise<Viewer> {
  if (userId === null) return anonymousViewer();

  const userIds = [...new Set([...articles.map((a) => a.authorId), ...extraUserIds])];
  const articleIds = articles.map((a) => a.id);

  const [follows, favorites] = await Promise.all([
    userIds.length
      ? prisma.follow.findMany({
          where: { followerId: userId, followedId: { in: userIds } },
          select: { followedId: true },
        })
      : Promise.resolve([]),
    articleIds.length
      ? prisma.favorite.findMany({
          where: { userId, articleId: { in: articleIds } },
          select: { articleId: true },
        })
      : Promise.resolve([]),
  ]);

  return {
    id: userId,
    followedUserIds: new Set(follows.map((f) => f.followedId)),
    favoritedArticleIds: new Set(favorites.map((f) => f.articleId)),
  };
}

export function profileJSON(user: ProfileSource & { id: number }, viewer: Viewer) {
  return {
    username: user.username,
    bio: user.bio ?? null,
    image: user.image ?? null,
    following: viewer.followedUserIds.has(user.id),
  };
}

/**
 * `withBody` is false for list endpoints: the spec's multiple-article payload
 * omits the `body` key entirely rather than sending it empty.
 */
export function articleJSON(
  article: ArticleWithRelations,
  viewer: Viewer,
  withBody = true,
): Record<string, unknown> {
  return {
    slug: article.slug,
    title: article.title,
    description: article.description,
    ...(withBody ? { body: article.body } : {}),
    tagList: article.tags.map((link) => link.tag.name).sort(),
    createdAt: article.createdAt.toISOString(),
    updatedAt: article.updatedAt.toISOString(),
    favorited: viewer.favoritedArticleIds.has(article.id),
    favoritesCount: article._count.favorites,
    author: profileJSON(article.author, viewer),
  };
}

export function commentJSON(comment: CommentWithRelations, viewer: Viewer) {
  return {
    id: comment.id,
    createdAt: comment.createdAt.toISOString(),
    updatedAt: comment.updatedAt.toISOString(),
    body: comment.body,
    author: profileJSON(comment.author, viewer),
  };
}

export function userJSON(user: AuthenticatedUser, token?: string) {
  return {
    email: user.email,
    token: token ?? signToken(user.id),
    username: user.username,
    bio: user.bio ?? null,
