import type { FastifyInstance } from 'fastify';
import { currentUser, hashPassword, requireAuth, signToken, verifyPassword } from '../auth.js';
import { alreadyTaken, invalidCredentials } from '../errors.js';
import { prisma } from '../prisma.js';
import { userJSON } from '../serializers.js';
import {
  envelope,
  nullableString,
  optionalRequiredString,
  present,
  requiredString,
  validatePassword,
} from '../validation.js';

/** Rejects a username/email that another account already owns. */
async function assertAvailable(fields: { username?: string; email?: string }, exceptUserId?: number) {
  if (fields.username !== undefined) {
    const owner = await prisma.user.findUnique({ where: { username: fields.username } });
    if (owner && owner.id !== exceptUserId) throw alreadyTaken('username');
  }
  if (fields.email !== undefined) {
    const owner = await prisma.user.findUnique({ where: { email: fields.email } });
    if (owner && owner.id !== exceptUserId) throw alreadyTaken('email');
  }
}

export async function userRoutes(app: FastifyInstance): Promise<void> {
  // POST /api/users — registration
  app.post('/api/users', async (request, reply) => {
    const payload = envelope(request.body, 'user');
    const username = requiredString(payload, 'username');
    const email = requiredString(payload, 'email');
    const password = validatePassword(payload['password']);

    await assertAvailable({ username, email });

    const user = await prisma.user.create({
      data: { username, email, password: await hashPassword(password) },
      select: { id: true, username: true, email: true, bio: true, image: true },
    });

    return reply.code(201).send({ user: userJSON(user) });
  });

  // POST /api/users/login
  app.post('/api/users/login', async (request, reply) => {
    const payload = envelope(request.body, 'user');
    const email = requiredString(payload, 'email');
    const password = requiredString(payload, 'password');

    const user = await prisma.user.findUnique({ where: { email } });
    if (!user || !(await verifyPassword(password, user.password))) {
      throw invalidCredentials();
    }

    return reply.send({ user: userJSON(user, signToken(user.id)) });
  });

  // GET /api/user — current user
  app.get('/api/user', { preHandler: requireAuth }, async (request, reply) => {
    return reply.send({ user: userJSON(currentUser(request)) });
  });

  // PUT /api/user — update current user
  app.put('/api/user', { preHandler: requireAuth }, async (request, reply) => {
    const user = currentUser(request);
    const payload = envelope(request.body, 'user');

    const username = optionalRequiredString(payload, 'username');
    const email = optionalRequiredString(payload, 'email');
    const bio = nullableString(payload, 'bio');
    const image = nullableString(payload, 'image');
    const password = present(payload, 'password')
      ? await hashPassword(validatePassword(payload['password']))
      : undefined;

    await assertAvailable({ username, email }, user.id);

    const updated = await prisma.user.update({
      where: { id: user.id },
      data: {
        ...(username !== undefined ? { username } : {}),
        ...(email !== undefined ? { email } : {}),
        ...(bio !== undefined ? { bio } : {}),
        ...(image !== undefined ? { image } : {}),
        ...(password !== undefined ? { password } : {}),
        updatedAt: new Date(),
      },
      select: { id: true, username: true, email: true, bio: true, image: true },
    });

    return reply.send({ user: userJSON(updated) });
  });
}

