import type { FastifyInstance, FastifyRequest } from 'fastify';
import { optionalAuth, requireAuth, currentUser } from '../auth.js';
import { notFound } from '../errors.js';
import { prisma } from '../prisma.js';
import { profileJSON, type Viewer } from '../serializers.js';

type UsernameParams = { username: string };

async function findProfile(username: string) {
  const user = await prisma.user.findUnique({
    where: { username },
    select: { id: true, username: true, bio: true, image: true },
  });
  if (!user) throw notFound('profile');
  return user;
}

function viewerFollowing(viewerId: number | null, followedIds: number[]): Viewer {
  return {
    id: viewerId,
    followedUserIds: new Set(followedIds),
    favoritedArticleIds: new Set(),
  };
}

async function followState(request: FastifyRequest, profileId: number): Promise<Viewer> {
  const viewerId = request.currentUser?.id ?? null;
  if (viewerId === null) return viewerFollowing(null, []);

  const link = await prisma.follow.findUnique({
    where: { followerId_followedId: { followerId: viewerId, followedId: profileId } },
  });
  return viewerFollowing(viewerId, link ? [profileId] : []);
}

export async function profileRoutes(app: FastifyInstance): Promise<void> {
  // GET /api/profiles/:username
  app.get<{ Params: UsernameParams }>(
    '/api/profiles/:username',
    { preHandler: optionalAuth },
    async (request, reply) => {
      const profile = await findProfile(request.params.username);
      return reply.send({ profile: profileJSON(profile, await followState(request, profile.id)) });
    },
  );

  // POST /api/profiles/:username/follow
  app.post<{ Params: UsernameParams }>(
    '/api/profiles/:username/follow',
    { preHandler: requireAuth },
    async (request, reply) => {
      const me = currentUser(request);
      const profile = await findProfile(request.params.username);

      if (profile.id !== me.id) {
        await prisma.follow.upsert({
          where: { followerId_followedId: { followerId: me.id, followedId: profile.id } },
          create: { followerId: me.id, followedId: profile.id },
          update: {},
        });
      }

      return reply.send({
        profile: profileJSON(profile, viewerFollowing(me.id, profile.id === me.id ? [] : [profile.id])),
      });
    },
  );

  // DELETE /api/profiles/:username/follow
  app.delete<{ Params: UsernameParams }>(
    '/api/profiles/:username/follow',
    { preHandler: requireAuth },
    async (request, reply) => {
      const me = currentUser(request);
      const profile = await findProfile(request.params.username);

      await prisma.follow.deleteMany({ where: { followerId: me.id, followedId: profile.id } });

      return reply.send({ profile: profileJSON(profile, viewerFollowing(me.id, [])) });
    },
  );
}

