import { randomBytes } from 'node:crypto';
import type { Prisma } from '@prisma/client';
import type { FastifyInstance } from 'fastify';
import { currentUser, optionalAuth, requireAuth } from '../auth.js';
import { forbidden, notFound } from '../errors.js';
import { prisma } from '../prisma.js';
import {
  articleInclude,
  articleJSON,
  buildViewer,
  type ArticleWithRelations,
} from '../serializers.js';
import { envelope, intParam, optionalRequiredString, requiredString, tagList } from '../validation.js';

type SlugParams = { slug: string };
type ListQuery = { tag?: string; author?: string; favorited?: string; limit?: string; offset?: string };
type FeedQuery = { limit?: string; offset?: string };

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

function slugifyTitle(title: string): string {
  const base = title
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 180);
  return base || 'article';
}

/** Duplicate titles are legal, so collisions get a short random discriminator. */
async function uniqueSlug(title: string): Promise<string> {
  const base = slugifyTitle(title);
  for (let attempt = 0; attempt < 10; attempt += 1) {
    const candidate = attempt === 0 ? base : `${base}-${randomBytes(4).toString('hex')}`;
    const taken = await prisma.article.findUnique({ where: { slug: candidate }, select: { id: true } });
    if (!taken) return candidate;
  }
  return `${base}-${randomBytes(12).toString('hex')}`;
}

/** Creates any missing tags and returns the nested-write payload for the join table. */
async function connectTags(names: string[]): Promise<Prisma.ArticleTagCreateWithoutArticleInput[]> {
  const tags = await Promise.all(
    names.map((name) =>
      prisma.tag.upsert({ where: { name }, create: { name }, update: {}, select: { id: true } }),
    ),
  );
  return tags.map((tag) => ({ tag: { connect: { id: tag.id } } }));
}

async function loadArticle(slug: string): Promise<ArticleWithRelations> {
  const article = await prisma.article.findUnique({ where: { slug }, include: articleInclude });
  if (!article) throw notFound('article');
  return article;
}

/** `updatedAt` must strictly advance so clients can detect the change. */
function nextUpdatedAt(previous: Date): Date {
  const now = new Date();
  return now.getTime() > previous.getTime() ? now : new Date(previous.getTime() + 1);
}

async function respondWithArticle(
  slug: string,
  viewerId: number | null,
): Promise<Record<string, unknown>> {
  const article = await loadArticle(slug);
  const viewer = await buildViewer(viewerId, [article]);
  return { article: articleJSON(article, viewer) };
}

async function listArticles(
  where: Prisma.ArticleWhereInput,
  query: FeedQuery,
  viewerId: number | null,
) {
  const limit = intParam(query.limit, DEFAULT_LIMIT, MAX_LIMIT);
  const offset = intParam(query.offset, 0);

  const [articlesCount, articles] = await Promise.all([
    prisma.article.count({ where }),
    prisma.article.findMany({
      where,
      include: articleInclude,
      // Second key breaks ties when two articles share a timestamp.
      orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
      skip: offset,
      take: limit,
    }),
  ]);

  const viewer = await buildViewer(viewerId, articles);
  return { articles: articles.map((a) => articleJSON(a, viewer, false)), articlesCount };
}

export async function articleRoutes(app: FastifyInstance): Promise<void> {
  // GET /api/articles/feed — registered before /:slug so the literal path wins
  app.get<{ Querystring: FeedQuery }>(
    '/api/articles/feed',
    { preHandler: requireAuth },
    async (request, reply) => {
      const me = currentUser(request);
      const where: Prisma.ArticleWhereInput = {
        author: { followers: { some: { followerId: me.id } } },
      };
      return reply.send(await listArticles(where, request.query, me.id));
    },
  );

  // GET /api/articles
  app.get<{ Querystring: ListQuery }>(
    '/api/articles',
    { preHandler: optionalAuth },
    async (request, reply) => {
      const { tag, author, favorited } = request.query;
      const where: Prisma.ArticleWhereInput = {
        ...(tag ? { tags: { some: { tag: { name: tag } } } } : {}),
        ...(author ? { author: { username: author } } : {}),
        ...(favorited ? { favorites: { some: { user: { username: favorited } } } } : {}),
      };
      return reply.send(await listArticles(where, request.query, request.currentUser?.id ?? null));
    },
  );

  // POST /api/articles
  app.post('/api/articles', { preHandler: requireAuth }, async (request, reply) => {
    const me = currentUser(request);
    const payload = envelope(request.body, 'article');

    const title = requiredString(payload, 'title');
    const description = requiredString(payload, 'description');
    const body = requiredString(payload, 'body');
    const tags = tagList(payload) ?? [];

    const created = await prisma.article.create({
      data: {
        slug: await uniqueSlug(title),
        title,
        description,
        body,
        authorId: me.id,
        tags: { create: await connectTags(tags) },
      },
      include: articleInclude,
    });

    const viewer = await buildViewer(me.id, [created]);
    return reply.code(201).send({ article: articleJSON(created, viewer) });
  });

  // GET /api/articles/:slug
  app.get<{ Params: SlugParams }>(
    '/api/articles/:slug',
    { preHandler: optionalAuth },
    async (request, reply) => {
      return reply.send(
        await respondWithArticle(request.params.slug, request.currentUser?.id ?? null),
      );
    },
  );

  // PUT /api/articles/:slug
  app.put<{ Params: SlugParams }>(
    '/api/articles/:slug',
    { preHandler: requireAuth },
    async (request, reply) => {
      const me = currentUser(request);
      const article = await loadArticle(request.params.slug);
      if (article.authorId !== me.id) throw forbidden('article');

      const payload = envelope(request.body, 'article');
      const title = optionalRequiredString(payload, 'title');
      const description = optionalRequiredString(payload, 'description');
      const body = optionalRequiredString(payload, 'body');
      const tags = tagList(payload);

      const updated = await prisma.article.update({
        where: { id: article.id },
        data: {
          ...(title !== undefined && title !== article.title
            ? { title, slug: await uniqueSlug(title) }
            : {}),
          ...(description !== undefined ? { description } : {}),
          ...(body !== undefined ? { body } : {}),
          // Omitting tagList preserves tags; an empty array clears them.
          ...(tags !== undefined
            ? { tags: { deleteMany: {}, create: await connectTags(tags) } }
            : {}),
          updatedAt: nextUpdatedAt(article.updatedAt),
        },
        include: articleInclude,
      });

      const viewer = await buildViewer(me.id, [updated]);
      return reply.send({ article: articleJSON(updated, viewer) });
    },
  );

  // DELETE /api/articles/:slug
  app.delete<{ Params: SlugParams }>(
    '/api/articles/:slug',
    { preHandler: requireAuth },
    async (request, reply) => {
      const me = currentUser(request);
      const article = await loadArticle(request.params.slug);
      if (article.authorId !== me.id) throw forbidden('article');

      await prisma.article.delete({ where: { id: article.id } });
      return reply.code(204).send();
    },
  );

  // POST /api/articles/:slug/favorite
  app.post<{ Params: SlugParams }>(
    '/api/articles/:slug/favorite',
    { preHandler: requireAuth },
    async (request, reply) => {
      const me = currentUser(request);
      const article = await loadArticle(request.params.slug);

      await prisma.favorite.upsert({
        where: { userId_articleId: { userId: me.id, articleId: article.id } },
        create: { userId: me.id, articleId: article.id },
        update: {},
      });

      return reply.send(await respondWithArticle(article.slug, me.id));
    },
  );

  // DELETE /api/articles/:slug/favorite
  app.delete<{ Params: SlugParams }>(
    '/api/articles/:slug/favorite',
    { preHandler: requireAuth },
    async (request, reply) => {
      const me = currentUser(request);
      const article = await loadArticle(request.params.slug);

      await prisma.favorite.deleteMany({ where: { userId: me.id, articleId: article.id } });

      return reply.send(await respondWithArticle(article.slug, me.id));
    },
  );
}

