import type { FastifyInstance } from 'fastify';
import { currentUser, optionalAuth, requireAuth } from '../auth.js';
import { forbidden, notFound } from '../errors.js';
import { prisma } from '../prisma.js';
import { buildViewer, commentInclude, commentJSON } from '../serializers.js';
import { envelope, requiredString } from '../validation.js';

type SlugParams = { slug: string };
type CommentParams = { slug: string; id: string };

async function loadArticleId(slug: string): Promise<{ id: number }> {
  const article = await prisma.article.findUnique({ where: { slug }, select: { id: true } });
  if (!article) throw notFound('article');
  return article;
}

export async function commentRoutes(app: FastifyInstance): Promise<void> {
  // GET /api/articles/:slug/comments
  app.get<{ Params: SlugParams }>(
    '/api/articles/:slug/comments',
    { preHandler: optionalAuth },
    async (request, reply) => {
      const article = await loadArticleId(request.params.slug);
      const comments = await prisma.comment.findMany({
        where: { articleId: article.id },
        include: commentInclude,
        orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
      });

      const viewerId = request.currentUser?.id ?? null;
      const viewer = await buildViewer(viewerId, [], comments.map((c) => c.authorId));
      return reply.send({ comments: comments.map((c) => commentJSON(c, viewer)) });
    },
  );

  // POST /api/articles/:slug/comments
  app.post<{ Params: SlugParams }>(
    '/api/articles/:slug/comments',
    { preHandler: requireAuth },
    async (request, reply) => {
      const me = currentUser(request);
      const article = await loadArticleId(request.params.slug);

      const payload = envelope(request.body, 'comment');
      const body = requiredString(payload, 'body');

      const comment = await prisma.comment.create({
        data: { body, articleId: article.id, authorId: me.id },
        include: commentInclude,
      });

      const viewer = await buildViewer(me.id, [], [comment.authorId]);
      return reply.code(201).send({ comment: commentJSON(comment, viewer) });
    },
  );

  // DELETE /api/articles/:slug/comments/:id
  app.delete<{ Params: CommentParams }>(
    '/api/articles/:slug/comments/:id',
    { preHandler: requireAuth },
    async (request, reply) => {
      const me = currentUser(request);
      const article = await loadArticleId(request.params.slug);

      const commentId = Number(request.params.id);
      const comment = Number.isInteger(commentId)
        ? await prisma.comment.findFirst({ where: { id: commentId, articleId: article.id } })
        : null;
      if (!comment) throw notFound('comment');
      if (comment.authorId !== me.id) throw forbidden('comment');

      await prisma.comment.delete({ where: { id: comment.id } });
      return reply.code(204).send();
    },
  );
}

