import Fastify, { type FastifyInstance } from 'fastify';
import { ApiError } from './errors.js';
import { articleRoutes } from './routes/articles.js';
import { commentRoutes } from './routes/comments.js';
import { profileRoutes } from './routes/profiles.js';
import { tagRoutes } from './routes/tags.js';
import { userRoutes } from './routes/users.js';

export type BuildOptions = { logger?: boolean };

export function buildApp(options: BuildOptions = {}): FastifyInstance {
  const app = Fastify({
    logger: options.logger ?? false,
    // Slugs are user-supplied, so keep the raw path as sent by the client.
    ignoreTrailingSlash: true,
  });

  app.decorateRequest('currentUser', null);

  // Bodyless POST/DELETE requests (favorite, follow) are valid; malformed JSON is a 422.
  app.addContentTypeParser(
    'application/json',
    { parseAs: 'string' },
    (_request, body: string, done) => {
      if (!body || body.trim() === '') return done(null, {});
      try {
        done(null, JSON.parse(body));
      } catch {
        done(new ApiError(422, { body: ['is invalid JSON'] }), undefined);
      }
    },
  );

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof ApiError) {
      return reply.code(error.statusCode).send({ errors: error.errors });
    }

    // Fastify's own body/parsing failures should read as validation errors.
    const statusCode = (error as { statusCode?: number }).statusCode ?? 500;
    if (statusCode >= 400 && statusCode < 500) {
      return reply.code(422).send({ errors: { body: [error.message] } });
    }

    reply.log.error(error);
    return reply.code(500).send({ errors: { server: ['internal error'] } });
  });

  app.setNotFoundHandler((_request, reply) => {
    return reply.code(404).send({ errors: { route: ['not found'] } });
  });

  app.register(userRoutes);
  app.register(profileRoutes);
  app.register(articleRoutes);
  app.register(commentRoutes);
  app.register(tagRoutes);

  app.get('/health', async () => ({ status: 'ok' }));

  return app;
}

